css:
.rc { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #222; }
.rc table { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
.rc-head td { vertical-align: middle; }
.rc-logo { width: 80px; }
.rc-logo img { max-width: 72px; max-height: 72px; }
.rc-school { text-align: center; }
.rc-school-name { font-size: 18px; font-weight: bold; text-transform: uppercase; }
.rc-motto { font-style: italic; }
.rc-contact { font-size: 10px; color: #555; }
.rc-title { text-align: center; font-size: 13px; font-weight: bold; border-top: 2px solid #0d3b66; border-bottom: 2px solid #0d3b66; padding: 4px; margin: 6px 0 8px; }
.rc-info td { padding: 2px 4px; }
.rc-marks th, .rc-marks td, .rc-summary td, .rc-attendance th, .rc-attendance td { border: 1px solid #999; padding: 3px 4px; text-align: center; }
.rc-marks th { background: #eef2f7; }
.rc-marks .rc-subject { text-align: left; }
.rc-attendance th { background: #eef2f7; text-align: left; }
.rc-position { font-size: 12px; }
.rc-comment { margin-top: 8px; min-height: 28px; border-bottom: 1px dotted #999; }
.rc-sign { text-align: right; margin: 4px 0 6px; }
.rc-foot td { padding: 4px 0; }
.rc-printed { text-align: right; color: #777; }
.rc-key { font-size: 9px; color: #555; }
.rc { position: relative; }
.rc-draft { position: absolute; top: 38%; left: 0; right: 0; text-align: center; font-size: 72px; font-weight: bold; color: rgba(200, 0, 0, 0.18); -webkit-transform: rotate(-30deg); transform: rotate(-30deg); z-index: 10; }
.rc-draft-note { margin: 6px 0; padding: 4px; border: 1px dashed #c00; color: #c00; font-size: 10px; }
.rc-verify { margin-top: 6px; }
.rc-verify td { vertical-align: middle; }
.rc-qr { width: 100px; }
.rc-qr img { width: 92px; height: 92px; }
.rc-verify-text { font-size: 10px; color: #333; }
.rc-verify-url { font-family: monospace; font-size: 9px; }
